const makeQuestion = ([question, options, answer, explanation], index, topic) => {
  const rotation = (index + topic.length) % options.length;
  return {
    question,
    options: [...options.slice(rotation), ...options.slice(0, rotation)],
    answer: (answer + options.length - rotation) % options.length,
    explanation,
  };
};

